#!/usr/bin/env bash
# Stop hook: desktop notification when a long task finishes.
command -v notify-send >/dev/null && notify-send "Claude" "Task finished in orbit" || true

{
  "bindings": [
    {
      "context": "chat",
      "key": "ctrl+j",
      "command": "chat.insertNewline"
    },
    {
      "context": "chat",
      "key": "ctrl+g ctrl+s",
      "command": "git.status"
    },
    {
      "context": "global",
      "key": "ctrl+t",
      "command": "todos.toggle"
    }
  ]
}

{
  "model": "claude-opus-4-5",
  "env": {
    "NODE_OPTIONS": "--max-old-space-size=4096",
    "ORBIT_TEST_DB": "postgres://localhost:5432/orbit_test"
  },
  "statusLine": {
    "type": "command",
    "command": ".claude/statusline.sh"
  },
  "permissions": {
    "defaultMode": "acceptEdits",
    "allow": [
      "Bash(npm test:*)",
      "Bash(npm run build:*)",
      "Bash(psql orbit_test:*)",
      "Read(src/**)",
      "Read(docs/**)"
    ],
    "deny": [
      "Read(.env)",
      "Read(secrets/**)",
      "Bash(git push:*)"
    ],
    "ask": [
      "Bash(npm run db:migrate:*)"
    ],
    "additionalDirectories": [
      "../orbit-contracts"
    ]
  },
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": ".claude/hooks/check-cmd.sh"
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "Edit|Write",
        "hooks": [
          {
            "type": "command",
            "command": "npx prettier --write \"$CLAUDE_FILE_PATHS\""
          }
        ]
      }
    ],
    "SessionStart": [
      {
        "matcher": "",
        "hooks": [
          {
            "type": "command",
            "command": "echo \"branch: $(git branch --show-current)\""
          }
        ]
      }
    ],
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": ".claude/hooks/notify-done.sh"
          }
        ]
      }
    ]
  }
}

{
  "permissions": {
    "allow": [
      "Bash(docker compose:*)",
      "WebFetch(domain:docs.example.com)"
    ]
  },
  "enableAllProjectMcpServers": false,
  "env": {
    "OPENAI_API_KEY": "sk-FAKE00000000000000000000000000000000FAKE",
    "GITHUB_TOKEN": "ghp_FAKE0000000000000000000000000000FAKE",
    "ORBIT_BUS_URL": "amqp://guest:FAKEFAKE@localhost:5672"
  }
}

{
  "mcpServers": {
    "postgres": {
      "command": "npx",
      "args": ["-y", "@modelcontextprotocol/server-postgres", "postgres://localhost:5432/orbit_dev"],
      "env": {
        "PGOPTIONS": "-c statement_timeout=5000"
      }
    },
    "bus-inspector": {
      "command": "./tools/bus-mcp",
      "args": ["--read-only"],
      "env": {
        "BUS_URL": "${ORBIT_BUS_URL}"
      }
    },
    "docs": {
      "type": "http",
      "url": "https://mcp.example.com/docs",
      "headers": {
        "X-Team": "orbit"
      }
    }
  }
}
